import React, { useState } from "react";
import { useOpenbase, getToken } from "../../../ppm/openbase/openbase";
import { CF_IMAGES_WORKER } from "../../../ppm/config/cfimages-worker-url";



export default function AuthTestOnly() {
  const { loading: obLoading } = useOpenbase();
  const [output, setOutput] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  if (obLoading) return "Initializing auth...";

  const handleAuthTest = async () => {
    setLoading(true);
    setOutput(null);

    try {
      const token = getToken();

      if (!token) {
        throw new Error("No auth token found");
      }

      console.log(token);

      const res = await fetch(
        `${CF_IMAGES_WORKER}/auth/test`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const data = await res.json();

      setOutput({
        success: res.ok,
        status: res.status,
        data,
      });

    } catch (err: any) {
      setOutput({
        success: false,
        error: err?.message || err,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: 20, fontFamily: "system-ui" }}>
      <button
        onClick={handleAuthTest}
        style={{
          padding: "10px 14px",
          borderRadius: 8,
          border: "1px solid #ddd",
          background: "#fff",
          cursor: "pointer"
        }}
      >
        Test Auth (Worker)
      </button>

      <div style={{
        marginTop: 16,
        padding: 12,
        border: "1px solid #eee",
        borderRadius: 8,
        background: "#fafafa",
        fontSize: 13,
        minHeight: 80
      }}>
        {loading ? "Running..." : output ? JSON.stringify(output, null, 2) : "No output yet"}
      </div>
    </div>
  );
}